  }, required: ['scenes', 'spine', 'sex_loop', 'capstones', 'lane2_anchor', 'lane3_depot', 'facility', 'budget_tally', 'frontier_seeds'],
}
const VERIFY_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    lens: { type: 'string' },
