input.script:
export const meta = {
  name: 'vesper-step6-feedback',
  description: 'Grade the complete A→A.5 blueprint against the content-framework (§1-§5), inversion- and chunk-aware; surface real gaps, credit by-design/frontier, go/no-go for authoring',
  phases: [
    { title: 'Grade', detail: 'parallel graders, one per framework subject + a completeness critic' },
    { title: 'Synthesize', detail: 'consolidate the actionable gaps, the by-design credits, the self-check, go/no-go' },
  ],
}

const GAME = '/Users/a0000/Desktop/Desktop_Archive_Backup/story_gen/story_gen_web_app/story_gen_django/games/vesper'
const SK = '/Users/a0000/Desktop/Desktop_Archive_Backup/story_gen/story_gen_web_app/story_gen_django/.claude/skills/author-game/references'

const CALIBRATION = `CALIBRATION — read before grading. This is the VESPER game, an INVERTED-PROTAGONIST sandbox, and we are grading the A->A.5 CHUNK (the opening + Mercer + Renner), NOT a whole game. The design DELIBERATELY excludes things the framework asks about — credit them, do NOT flag them as gaps:
- She has NO personal corruption ladder (left dead), NO solo-sexual content (cut, deferred to Act 2), NO personal exhibitionism (her 'being-seen' is the instrumental cover ladder), NO feeling/humanity meter. Her one axis is the AWAKENING (chip + glitch-dread). The supply->demand feeder economy DISSOLVES by design (NPC rungs gate on the NPC's own traits, not a player-corruption door).
- The economy is deliberately LIGHT (a kept asset; thin sinks; the disguise shop + Pell upgrades are FRONTIER). NO hard fail-state in the chunk (charge = soft pace; the leash->enforcers->hunt is a Phase-1-wide ramp, frontier).
- A.5->B is FRONTIER, telegraphed not built: Bastien/Calloway/Cain/Pell/Sol/the units, Mid-City + other venues, the world's full reactive-public layer, and THE FRONTIER ITSELF (the_site / the chip / the fracture = the Phase-1 cliffhanger). These are honest build-order defers, logged + telegraphed (greyed seeds / locked cards).
The design book states its own 'None by design' and 'Deferred (Act 2)' and 'Frontier' lists — READ THEM and credit them. A cluster is only a GAP if the design CLAIMS to deliver it (or the framework names something load-bearing the design forgot), and the blueprint doesn't. Use verdicts: held / refine (thin) / gap (real hole) / by-design-NA (deliberately excluded, credited) / frontier-defer (telegraphed, built later). Only 'refine' and 'gap' are actionable.`

const CLUSTER = {
  type: 'object', additionalProperties: false,
  properties: {
    cluster: { type: 'string', description: 'the framework cluster, e.g. "§1B desire ladder" or "§3D Renner everyday content"' },
    verdict: { type: 'string', description: 'held | refine | gap | by-design-NA | frontier-defer' },
    evidence: { type: 'string', description: 'where in design_book.md it is answered (or why it is N/A / frontier)' },
    fix: { type: 'string', description: 'for refine/gap only: the concrete fix, in plain language' },
    severity: { type: 'string', description: 'for refine/gap only: MAJOR | NOTABLE | MINOR (else empty)' },
    bounces_to: { type: 'string', description: 'for refine/gap only: which layer the fix lands in — Step2 / Step4-story / Step5-blueprint (else empty)' },
  }, required: ['cluster', 'verdict', 'evidence'],
}
const GRADER = {
  type: 'object', additionalProperties: false,
  properties: {
    subject: { type: 'string' },
    verdicts: { type: 'array', items: CLUSTER },
    summary: { type: 'string', description: 'one-paragraph verdict for this subject + any standout gap' },
  }, required: ['subject', 'verdicts', 'summary'],
}

phase('Grade')
const lenses = [
  { key: '§1 Shape', focus: `Grade §1 (The Fantasy & Shape — A the hungry sentence, B the desire ladder + payoffs + visible-next-rung + reactive-cause-stated-in-opening, C act shape + the FAIL-STATE declaration, D the declared desire span, E the opening [first screen, 2-3 things doable at zero with one downward nudge, first named want, 10-minute taste, premise-named-on-the-page, customize speak-back] + the systems ON/OFF declaration, F the frontier). CHUNK NOTE: §1F frontier = the chip/fracture cliffhanger (frontier-defer, telegraphed); §1C fail-state = 'no hard fail in chunk' is a DELIBERATE declaration (credit it, not a gap). Focus hard on §1E — the opening's 10-min-taste + premise-on-the-page (the prior build's node-collapse was an §1E-adjacent failure; the blueprint now splits to ~23 nodes — confirm that lands the taste).` },
  { key: '§2 YOU', focus: `Grade §2 (the player's own thread — 2A bootstrap, 2B exhibition, 2C economy/income/sinks/items/pressure, 2D ceiling + other ladders, 2E supply-vs-demand + the fused-unit roster). INVERSION-CRITICAL: 2A solo act / 2B personal exhibition / the personal-corruption ladder are CUT by design (by-design-NA, credit). The real checks: is the CRADLE a fused unit (the glitch-recurrence = the 'walk-in' on her downtime — confirm it's not a dead-bath bare-restore)? Is 2C economy real (Renner income, thin-but-honest sinks, charge pressure)? Is 2E correctly DISSOLVED (no player-corruption door => no feeder count to close)? Does she have ANY in-chunk progression (the glitch beats + targets falling + the chip un-fed-but-seeded) — is that enough, or does the chunk read as no-progression-for-the-player (a real concern worth a 'refine' if so)?` },
  { key: '§3 Mercer', focus: `Grade §3 for MERCER (A who/want/teeth, B on-ramp ungated cold-start, C arc start-to-end, D everyday content [the 4 use-scenes: hub/chore-hijack/summons/invasion + catch-with-another], E milestones [first-Penthouse-service, first invasion], F voice + ceiling, G repeatable loop). NOTE: Mercer's arc = NONE by design (unchanging/oblivious owner) — §3C 'arc' is by-design-NA (credit). His double-lock EXEMPTION is sanctioned. Check: is his on-ramp ungated (first penthouse visit)? Do the 4 use-scenes each land a distinct note? Is the loop his-POV with no drain? Voice carried in dialog (Rule 4)?` },
  { key: '§3 Renner', focus: `Grade §3 for RENNER (A who/want/teeth, B on-ramp [the hire], C arc [the 8-step climb], D everyday [the rungs + rising walk-ins + the Anchor witness/cheer-up], E milestones [hire/blowjob/anal-drain + morning-afters], F voice [the reaction-climb] + ceiling, G repeatable loop [the sex machine]). This is the big arc, just blueprinted in depth (19+2) — expect mostly 'held'. Check for any THIN cluster: is the double-lock present on every lewd rung? Is the voice carried in his own dialog at the hot beats (Rule 4, the reaction bands)? Does the loop have real in-menu variety? Is §3H (what the arc SETS) wired (renner_drained + renner_leads_extracted)?` },
  { key: '§4 Reactivity', focus: `Grade §4 (reactivity — 4A when HER state crosses [the glitch-recurrences on worked_renner_once/renner_drained], 4B when a PERSON changes [the morning-afters; Mercer's invasion arming], 4C outfit-reactive world, 4D wallet/day/place/body-state crossings, 4E THE MACHINE/DAG [core loop closed, every core NPC placed, no cycle, no entry gated, every cross-gate telegraphed], 4F loses-ground [the negative axis]). WHOLE-GAME CHECK: run §4E the DAG verify HARD (it's the deadlock-the-build-wont-catch check) — but chunk-scoped (the chunk DAG, with frontier reads as telegraphed seeds). NOTE: 4C outfit-reactive = clothing-is-narrative-in-chunk (by-design-NA / frontier); 4F loses-ground = 'no fail in chunk' (credit the §1C declaration). Is the cross-NPC seam (worked_renner_once feeding BOTH the player glitch AND Mercer's invasion) sound and acyclic?` },
  { key: '§5 World', focus: `Grade §5 (the world — 5A every place earns its click [the ~11 built; the dead-room gate], 5B the place ceilings, 5C reactive public + risks, 5D the clock/schedules/offscreen, 5E cadence & pressure clock, 5F phone + sidebar/HUD [Charge+Credits, the Mission-1 card, hidden meters], 5G access & travel [the bridge, the_site locked-visible, why-it-opened], 5H shared-private). NOTE: most frontier venues are frontier-defer (credit); 5C reactive-public is thin in chunk (the living-city fills with later missions — refine-or-frontier, your call); 5H shared-private = NONE by design (credit). Check 5A HARD: does every BUILT location earn its click (no dead room)? Is the_site a telegraphed locked-visible card (not a silent gap)? Does the container double-print fix cover the nav?` },
  { key: 'Critic', focus: `You are the COMPLETENESS CRITIC. Run the step-6 'Self-check before authoring' list (read ${SK}/step-6-feedback.md lines ~41-73) against the whole blueprint: both tracks present · daily loop live not décor · shared-private built right (N/A here) · every scene serves a WANT · tiers populated · economy balanced (dissolved here) · the machine verified · reactivity present incl. loses-ground · VOICE CARRIAGE Rule 4 (per NPC, are the hub + hot/capstone beats carried by the character's own dialog, not narrated-about?) · systems declared · archetypes/places fit · ceilings honored (kink-ceilings) · NO SILENT CAPS (every defer is a telegraphed seed). THEN ask the hard question: what is MISSING that none of the subject-graders would catch — a load-bearing thing the design forgot, a cross-cutting drift, a claim the blueprint makes but doesn't deliver? Be adversarial. Credit by-design/frontier per the calibration.` },
]
const grades = await parallel(lenses.map(l => () => agent(
  `You are grading the Vesper A->A.5 blueprint against the content-framework as Step 6 (feedback). Read-only, do not edit.

${CALIBRATION}

READ FULLY: ${SK}/content-framework.md (the question set), ${SK}/step-6-feedback.md (the method + the self-check list), ${GAME}/design_book.md (the WHOLE blueprint + the design's own 'none by design' / 'deferred' / 'frontier' declarations — credit them). Pull doctrine as needed (${SK}/lanes.md, ${SK}/rts-flat-prose.md for voice-carriage Rule 4, ${SK}/trait-design.md, ${SK}/kink-ceilings.md).

YOUR LENS: ${l.focus}

For each cluster in your lens return a verdict (held / refine / gap / by-design-NA / frontier-defer) with evidence; for refine/gap give the concrete fix + severity (MAJOR/NOTABLE/MINOR) + which layer it bounces to. Be calibrated — most framework 'no answers' here are deliberate exclusions or honest frontier defers, NOT gaps. A real gap is something the design claims-but-doesn't-deliver, or a load-bearing thing it forgot. Return per schema.`,
  { label: `grade:${l.key}`, phase: 'Grade', schema: GRADER })))

phase('Synthesize')
const synth = await agent(
  `You are the lead reviewer closing Step 6 (feedback) for the Vesper A->A.5 blueprint. Consolidate the seven graders into a go/no-go for authoring. Read-only — produce the report, do not edit.

${CALIBRATION}

The seven graded subjects (§1 Shape, §2 YOU, §3 Mercer, §3 Renner, §4 Reactivity, §5 World, Critic):
${JSON.stringify(grades.filter(Boolean), null, 2)}

Produce:
1. ACTIONABLE GAPS only (verdict gap or refine) — deduped across graders, severity-ranked (MAJOR first), each with: cluster, what's missing, the concrete fix, and which layer it bounces to (Step2 / Step4-story / Step5-blueprint). If there are zero MAJOR gaps, say so plainly.
2. BY-DESIGN CREDITED — the deliberate exclusions the graders confirmed (so LO sees what was correctly NOT flagged).
3. FRONTIER-DEFERRED — the telegraphed seeds confirmed as honest build-order defers (not silent cuts).
4. SELF-CHECK results — the step-6 'before authoring' checklist, pass/flag each.
5. GO / NO-GO — is the blueprint ready for Step 7 authoring? If gaps exist, which MUST be fixed first (MAJOR/NOTABLE) vs which can ride as a telegraphed seed. Recommend the disposition for each actionable gap (fix-now / defer-as-seed / leave).
Keep it plain and concrete — this becomes a propose-first report to LO. Do not edit any file.`,
  { label: 'synthesize:step6', phase: 'Synthesize', schema: {
    type: 'object', additionalProperties: false,
    properties: {
      go_no_go: { type: 'string' },
      actionable_gaps: { type: 'array', items: { type: 'object', additionalProperties: false, properties: {
        cluster: { type: 'string' }, severity: { type: 'string' }, what: { type: 'string' }, fix: { type: 'string' }, bounces_to: { type: 'string' }, disposition: { type: 'string', description: 'fix-now / defer-as-seed / leave' },
      }, required: ['cluster', 'severity', 'what', 'fix', 'disposition'] } },
      by_design_credited: { type: 'array', items: { type: 'string' } },
      frontier_deferred: { type: 'array', items: { type: 'string' } },
      self_check: { type: 'array', items: { type: 'object', additionalProperties: false, properties: { check: { type: 'string' }, result: { type: 'string' }, note: { type: 'string' } }, required: ['check', 'result'] } },
      recommendation: { type: 'string' },
    }, required: ['go_no_go', 'actionable_gaps', 'by_design_credited', 'frontier_deferred', 'self_check', 'recommendation'],
  } })

return { synth, grades: grades.filter(Boolean) }

