export const meta = {
  name: 'vesper-exitblock-bug-diagnose',
  description: 'Diagnose why a same-node "show more" link and the exit-block link both render at once in the built Vesper game; place the bug in a layer (engine/TOML/skill) read-only',
  phases: [
    { title: 'Investigate' },
    { title: 'Synthesize' },
  ],
}

const FINDING_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    summary: { type: 'string', description: 'Plain-language summary of what was found' },
    citations: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          file: { type: 'string' },
          lines: { type: 'string', description: 'line number or range, e.g. 14397 or 14380-14420' },
          what: { type: 'string', description: 'what this code/TOML does, quoted or paraphrased' },
        },
        required: ['file', 'lines', 'what'],
      },
    },
    verdict: { type: 'string', description: 'The specific answer to this agent\'s question' },
  },
  required: ['summary', 'citations', 'verdict'],
}

const V2 = 'apps/game_generation/twee_comprehensive/generators/v2.py'

phase('Investigate')

const [engine, toml, skill] = await parallel([
  // ---- ENGINE: how does a node render forward/continue links + the exit block, and can both show at once? ----
  () => agent(
    `You are debugging the Story-Gen Twee/SugarCube generator. Read ${V2} (≈18k lines) and answer ONE question precisely:

When a single CANVAS NODE is rendered into a SugarCube passage, how are these two things emitted, and CAN THEY BOTH BE VISIBLE AT THE SAME TIME?

  (A) An in-canvas forward/"show more"/"continue" link — a choice with targetType="node" that routes to ANOTHER node within the SAME canvas (reveals the next beat of content without leaving the canvas). Also look for any "read more"/reveal/cascade mechanism that shows more text in the same node.

  (B) The node's EXIT BLOCK — search for: exit_block, exitBlock, "exit", the choices that leave the canvas / go back to the hub / to a location. Find how exit_block is parsed and rendered.

Trace the actual rendering code path that decides which links a node shows. Find the EXACT conditional logic (file:line) that governs whether the exit block renders. The bug being investigated: in the live game, a node shows BOTH a "go to next node (more content)" link AND the exit-block link at the same time; the author expected the exit block to be HIDDEN while the forward/continue link is present.

Report:
- How node-routing choices (targetType=node, same canvas) are emitted (file:line).
- How exit_block is parsed + rendered (file:line).
- The precise condition under which the exit block renders alongside forward links (file:line). Is there ANY suppression logic ("hide exit when a forward node link exists")? If not, say so explicitly.
- Whether this is engine behavior (exit always renders) vs author-controllable (e.g. exit only renders if author omits forward choices / uses conditions).

Ground every claim in file:line from ${V2}. Do not speculate beyond the code.`,
    { label: 'engine:node-exit-render', phase: 'Investigate', schema: FINDING_SCHEMA, effort: 'high' }
  ),

  // ---- GAME TOML: which Vesper canvas/node actually produces both links at once? ----
  () => agent(
    `Read every file in games/vesper/toml_phases/ EXCEPT 7_final_game.toml (that one is generated; ignore it). Files: 0_systems_spec.toml, 1_metadata_and_locations.toml, 2_one_shots.toml, 3_activities.toml, 5_scenes.toml.

Find every CANVAS that has BOTH of these in the SAME node (or same canvas where one node both continues and exits):
