#!/usr/bin/env python3
"""
Stitch the Vesper conversation sessions into one faithful, readable history.

Reads the raw Claude Code session transcripts (.jsonl) listed in SESSIONS,
merges all events by timestamp, dedups by uuid, and emits:
  - conversation-transcript.md  (readable: user verbatim, assistant text verbatim,
                                 foldable thinking, one-line tool summaries, numbered
                                 user exchanges, session-boundary markers)
  - raw-transcript.jsonl        (lossless: the merged+deduped+sorted raw events)

FAITHFULNESS: user words and assistant text are copied verbatim from disk — never
paraphrased. Only structural wrappers (<system-reminder>, <command-*>, local-command
caveats) are stripped from user turns so the actual words read clean.

Re-run:  python3 build_transcript.py
"""
import json
import os
import re

# The Vesper session chain (newest content lives in 8e47ba21; 3013838e is a short
# "continue authoring vesper" side-session). Different games / skill-redesign
# precursors are intentionally excluded.
SRC_DIR = "/Users/a0000/.claude/projects/-Users-a0000-Desktop-Desktop-Archive-Backup-story-gen-story-gen-web-app-story-gen-django"
SESSIONS = [
    "8e47ba21-c47f-46e7-a2e1-a1aabdceb1d8.jsonl",
    "3013838e-5df5-4913-b8bd-41d7d44f809e.jsonl",
]
OUT_DIR = os.path.dirname(os.path.abspath(__file__))
TRANSCRIPT_MD = os.path.join(OUT_DIR, "conversation-transcript.md")
RAW_JSONL = os.path.join(OUT_DIR, "raw-transcript.jsonl")

# ---- wrapper stripping for user turns -------------------------------------------------
_WRAPPER_TAGS = [
    "system-reminder", "command-name", "command-message", "command-args",
    "command-stdout", "local-command-stdout", "local-command-caveat",
    "command-output", "stdout",
]


def strip_wrappers(text):
    """Remove the structural tags Claude Code injects, keep the user's real words."""
    if not text:
        return ""
    for tag in _WRAPPER_TAGS:
        text = re.sub(rf"<{tag}>.*?</{tag}>", "", text, flags=re.DOTALL)
    # Drop the long auto-injected blocks that have no closing tag pattern we kept.
    text = re.sub(r"<local-command-caveat>.*?</local-command-caveat>", "", text, flags=re.DOTALL)
    return text.strip()


def block_text(content, kind):
    """Pull concatenated text of a given block kind ('text'|'thinking') from content."""
    out = []
    if isinstance(content, list):
        for b in content:
            if isinstance(b, dict) and b.get("type") == kind:
                out.append(b.get("text", "") or b.get("thinking", ""))
    return "\n".join(out).strip()


def user_text(content):
    """The user's typed text (string or content-array), wrappers stripped."""
    if isinstance(content, str):
        return strip_wrappers(content)
    if isinstance(content, list):
        parts = []
        for b in content:
            if isinstance(b, dict) and b.get("type") == "text":
                parts.append(b.get("text", ""))
        return strip_wrappers("\n".join(parts))
    return ""


def has_tool_result(content):
    return isinstance(content, list) and any(
        isinstance(b, dict) and b.get("type") == "tool_result" for b in content
    )


def tool_use_summary(b):
    """One-line summary of an assistant tool_use block."""
    name = b.get("name", "tool")
    inp = b.get("input", {}) or {}
    hint = ""
    if name == "Bash":
        hint = inp.get("description") or (str(inp.get("command", ""))[:70])
    elif name in ("Edit", "Write", "Read", "NotebookEdit"):
        hint = os.path.basename(str(inp.get("file_path", "")))
    elif name == "Workflow":
        m = re.search(r"name:\s*'([^']+)'", str(inp.get("script", "")))
        hint = m.group(1) if m else (inp.get("name") or "inline script")
    elif name == "Task" or name == "Agent":
        hint = inp.get("description") or inp.get("subject") or ""
    elif name.startswith("Task"):
        hint = inp.get("subject") or inp.get("taskId") or ""
    elif name == "Skill":
        hint = inp.get("skill") or ""
    elif name == "AskUserQuestion":
        qs = inp.get("questions") or []
        hint = qs[0].get("question", "")[:60] if qs else ""
    else:
        # generic: first short scalar arg
        for k, v in inp.items():
            if isinstance(v, str) and v:
                hint = f"{k}={v[:50]}"
                break
    hint = re.sub(r"\s+", " ", str(hint)).strip()
    return f"[{name}] {hint}".rstrip()


def tool_result_summary(content):
    """One-line summary of a user tool_result payload."""
    for b in content:
        if isinstance(b, dict) and b.get("type") == "tool_result":
            c = b.get("content", "")
            if isinstance(c, list):
                txt = ""
                for x in c:
                    if isinstance(x, dict) and x.get("type") == "text":
                        txt += x.get("text", "")
                c = txt
            c = re.sub(r"\s+", " ", str(c)).strip()
            n = len(c)
            err = " ERROR" if "error" in c[:60].lower() else ""
            return f"[tool result{err}: {n} chars] {c[:90]}"
    return "[tool result]"


# ---- load + merge ---------------------------------------------------------------------
events = []
seen_uuid = set()
per_session = {}
for si, fn in enumerate(SESSIONS):
    path = os.path.join(SRC_DIR, fn)
    sid = fn[:36]
    cnt = 0
    with open(path, encoding="utf-8", errors="replace") as fh:
        for ln, line in enumerate(fh):
            line = line.rstrip("\n")
            if not line.strip():
                continue
            try:
                ev = json.loads(line)
            except json.JSONDecodeError:
                continue
            uid = ev.get("uuid")
            if uid and uid in seen_uuid:
                continue
            if uid:
                seen_uuid.add(uid)
            ev["_src"] = sid
            ev["_order"] = (si, ln)
            ev["_raw"] = line
            events.append(ev)
            cnt += 1
    per_session[sid] = cnt

# sort by timestamp, then by source order as tiebreak
events.sort(key=lambda e: (e.get("timestamp") or "", e["_order"]))

# ---- emit raw merged jsonl (lossless) -------------------------------------------------
with open(RAW_JSONL, "w", encoding="utf-8") as out:
    for ev in events:
        out.write(ev["_raw"] + "\n")

# ---- emit readable transcript ---------------------------------------------------------
exchange = 0
n_user = 0
n_asst = 0
n_think = 0
n_tool = 0
cur_session = None
first_ts = last_ts = None
lines = []

for ev in events:
    typ = ev.get("type")
    ts = ev.get("timestamp")
    if ts:
        if first_ts is None:
            first_ts = ts
        last_ts = ts
    # skip subagent / sidechain internals in the readable thread
    if ev.get("isSidechain"):
        continue
    msg = ev.get("message") or {}
    content = msg.get("content")

    # session-boundary marker
    if ev.get("_src") != cur_session and typ in ("user", "assistant"):
        cur_session = ev.get("_src")
        lines.append(f"\n---\n\n> ⟦ session `{cur_session}` ⟧  ({str(ts)[:19]})\n")

    if typ == "user":
        # real user turn vs tool_result echo
        if has_tool_result(content) and not user_text(content):
            continue  # tool result — not part of the dialogue
        txt = user_text(content)
        if not txt:
            continue  # pure system-reminder / command wrapper, no real words
        exchange += 1
        n_user += 1
        lines.append(f"\n## [{exchange}] 🧑 LO\n\n{txt}\n")

    elif typ == "assistant":
        if not isinstance(content, list):
            content = [{"type": "text", "text": str(content)}] if content else []
        for b in content:
            if not isinstance(b, dict):
                continue
            bt = b.get("type")
            if bt == "thinking":
                think = (b.get("thinking", "") or b.get("text", "")).strip()
                if think:
                    n_think += 1
                    lines.append(
                        "\n<details><summary>💭 thinking</summary>\n\n"
                        + think + "\n\n</details>\n"
                    )
            elif bt == "text":
                t = (b.get("text", "")).strip()
                if t:
                    n_asst += 1
                    lines.append(f"\n**🤖 ENI:** {t}\n")
            elif bt == "tool_use":
                n_tool += 1
                lines.append(f"\n&nbsp;&nbsp;`{tool_use_summary(b)}`\n")

header = f"""# Vesper — Stitched Conversation History

Faithful, turn-by-turn record of the Vesper authoring conversation, stitched from the
raw Claude Code session transcripts on disk (NOT reconstructed from memory). User words
and assistant replies are verbatim; only structural wrappers were stripped. Thinking
blocks are included (foldable) because that is where the iteration reasoning — and the
inefficiencies worth studying — actually live. Tool calls are one-line summaries.

**Sessions stitched:** {', '.join('`'+s[:36]+'`' for s in SESSIONS)}
**Range:** {str(first_ts)[:19]} … {str(last_ts)[:19]}
**Counts:** {exchange} user exchanges · {n_asst} assistant replies · {n_think} thinking blocks · {n_tool} tool calls
**Per-session events (deduped):** {', '.join(f'{k[:8]}={v}' for k,v in per_session.items())}

Subagent/workflow internals (sidechains) are excluded from this readable thread; they
remain in `raw-transcript.jsonl`.

---
"""

with open(TRANSCRIPT_MD, "w", encoding="utf-8") as out:
    out.write(header)
    out.write("".join(lines))

print(f"events merged (deduped): {len(events)}")
print(f"per-session: {per_session}")
print(f"user exchanges: {exchange}  asst: {n_asst}  thinking: {n_think}  tools: {n_tool}")
print(f"range: {str(first_ts)[:19]} .. {str(last_ts)[:19]}")
print(f"wrote: {TRANSCRIPT_MD}")
