// Focused live play-test of Vesper's opening + the locked_text fix.
// Run from the twine-game-explorer skill dir so require('playwright') resolves.
const { chromium } = require('playwright');

const FILE = 'file://' + process.argv[2];
const ARMING = [
  "gives it back by morning",          // Charge armed (cradle night beat)
  "company credits, for clothes",      // Credits armed (dossier)
  "understands the leash",             // win/fail leash surfaced (office)
];
const LOCKED = [
  "Not on the floor — earn the office first.",
  "He's barely warmed to you yet.",
  "Not till he's flirting back and wants your hands on him.",
  "He needs you badly first — and he hasn't had your mouth yet.",
  "He's not close enough yet.",
];

(async () => {
  const out = { errors: [], opening: {}, locked: {} };
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.on('pageerror', e => out.errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') out.errors.push('console: ' + m.text()); });

  await page.goto(FILE, { waitUntil: 'load' });
  await page.waitForFunction(
    () => window.SugarCube && window.SugarCube.State && document.querySelector('#passages .passage'),
    { timeout: 20000 }
  );

  const snap = () => page.evaluate(() => document.querySelector('#passages').innerText || '');
  const openingDone = () => page.evaluate(() => !!window.SugarCube.State.variables.opening_done);

  // ---- PART 1: walk the opening funnel ----
  const seen = [await snap()];
  let steps = 0;
  while (steps < 120 && !(await openingDone())) {
    const links = page.locator('#passages .passage a.link-internal');
    const n = await links.count();
    let clicked = false;
    for (let i = 0; i < n; i++) {
      const lk = links.nth(i);
      if (await lk.isVisible().catch(() => false)) {
        await lk.click().catch(() => {});
        await page.waitForTimeout(100);
        seen.push(await snap());
        clicked = true; steps++;
        break;
      }
    }
    if (!clicked) break;
  }
  const full = seen.join('\n');
  out.opening.reached_city = await openingDone();
  out.opening.steps = steps;
  out.opening.final_location = await page.evaluate(() => window.SugarCube.State.variables.player_location || window.passage && window.passage() || '');
  out.opening.arming_lines_rendered = ARMING.map(s => ({ s, ok: full.includes(s) }));
  out.opening.errors_during_opening = out.errors.length;

  // ---- PART 2: drive straight to a locked rung, read its greyed reason live ----
  const lockedTitles = await page.evaluate(() => {
    try {
      const V = window.SugarCube.State.variables;
      V.opening_done = true; V.renner_hired = true; V.renner_office_open = false; // keep rungs locked
      window.SugarCube.Engine.play('Canvas_hub_depot_floor_Node_1');
      return Array.from(document.querySelectorAll('#passages [title]')).map(e => e.getAttribute('title'));
    } catch (e) { return ['ERR:' + e.message]; }
  });
  await page.waitForTimeout(150);
  out.locked.titles_rendered = lockedTitles;
  out.locked.matches = LOCKED.map(s => ({ s, ok: lockedTitles.includes(s) }));
  // greyed span check: locked choices render as <span> with a 'locked' class, not <a>
  out.locked.greyed_span_count = await page.evaluate(() =>
    document.querySelectorAll('#passages .passage span[title]').length
  );
  await page.screenshot({ path: '/tmp/vesper_depot_locked.png' }).catch(() => {});

  out.errors_total = out.errors.length;
  await browser.close();
  console.log(JSON.stringify(out, null, 2));
})().catch(e => { console.log('FATAL ' + e.message); process.exit(1); });

